/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// </summary>
internal final class METTMSEngineSalesOrderProccess_PackingSlip extends METTMSEngineSalesOrderProccess
{
    METSalesOrderShipmentLoadHeader salesOrderShipmentLoadHeader;
    METSalesOrderShipmentLoadLines  salesOrderShipmentLoadLines, salesOrderShipmentLoadLinesQueryRun;
    PackingSlipId                   packingSlipId; 
    WMSPickingRouteID               pickingRouteId;
    METTMSCCRTableHelper            ccrHelper;
    Set                             ccrToteIds;
    METWMSPicklistNumber            wmsPicklistNumber;

}

Method.Source:
/// <summary>
/// New method
/// </summary>
/// <param name = "_salesOrderShipmentLoadHeader">SO finalisation shipment load header</param>
/// <param name = "_packingSlipId">Delivery note number</param>
public void new(METSalesOrderShipmentLoadHeader  _salesOrderShipmentLoadHeader, PackingSlipId _packingSlipId)
{
    // Shipment record being confirmed
    salesOrderShipmentLoadHeader = _salesOrderShipmentLoadHeader;

    // Generated delivery note number
    packingSlipId = _packingSlipId; 

    // initialise the Set for CCR Tote ID, object instanciated here but not used for CB624, only CB626
    ccrToteIds = new Set(Types::String);
}

/// <summary>
/// Create an instance of <c>METTMSEngineLinesTmpBuilder</c>
/// </summary>
/// <param name = "_tmsEngineProcess">METTMSEngineSalesOrderProcess enum</param>
/// <param name = "_salesTable"><c>SalesTable</c> record</param>
/// <returns>New instance of <c>METTMSEngineLinesTmpBuilder</c></returns>
METTMSEngineLinesTmpBuilder getTmpBuilderInstance(METTMSEngineSalesOrderProcess _tmsEngineProcess, SalesTable _salesTable)
{
    return METTMSEngineLinesTmpBuilder::construct(METTMSEngineSalesOrderProcess::PackingSlip, _salesTable, salesOrderShipmentLoadHeader.ShipmentId, wmsPicklistNumber);
}

/// <summary>
/// Initialise temporary table with calculations and CCR if required.
/// </summary>
void initTmpTable()
{
    super();

    // if there is at least one line with CCR
    if (hasCCR)
    {
        // Trigger the CCR calculation
        ccrHelper = METTMSCCRTableHelper::construct(proccessLinesTmp,
                                                    ccrToteIds,
                                                    salesTable.SalesId,
                                                    wmsPicklistNumber);

        // calc CCR variables and returns set of unique tote ids to avoid double counting for the next SOs
        ccrToteIds = ccrHelper.calc();
    }
}

/// <summary>
/// Retrieve the METTMSShipmentOrderTable record based on the TMS engine delivery note posting logic
/// </summary>
/// <param name = "_salesId">Sales order number</param>
/// <param name = "_pickingRouteId">Picking list number</param>
/// <returns><c>METTMSShipmentOrderTable</c> record found or empty.</returns>
protected METTMSShipmentOrderTable getTMSShipmentOrderTable(SalesIdBase _salesId, WMSPickingRouteID _pickingRouteId = '')
{
    METTMSShipmentOrderTable TMSShipmentOrderTable;

    // check to see if there is a TSO with Order number = SalesOrderID, and Pick List ID = PickListID that this order is being added to
    TMSShipmentOrderTable = super(_salesId, salesOrderShipmentLoadLines.PickingListNum);

    if (!TMSShipmentOrderTable)
    {
        // check to see if there is a TSO with Order number = SalesOrderID, and Pick List ID is blank (order had only been processed at creation, and something went wrong at SO Extraction)
        TMSShipmentOrderTable = super(_salesId, METConstants::emptyString);
    }

    return TMSShipmentOrderTable;
}

/// <summary>
/// Run the TMS engine
/// </summary>
public void run()
{        
    SalesTable salesTableLoop;

    // For each combination of sales order - picking list number in the F&O finalisation shipment lines
    while select salesOrderShipmentLoadLines
        group by ShipmentId, OrderNum, PickingListNum          
           where salesOrderShipmentLoadLines.ShipmentId == salesOrderShipmentLoadHeader.ShipmentId
    {
        pickingRouteId = salesOrderShipmentLoadLines.PickingListNum;          

        // cannot join in the while select because of the group by...
        salesTableLoop = SalesTable::find(salesOrderShipmentLoadLines.OrderNum);

        this.init(salesTableLoop);

        wmsPicklistNumber = WMSPickingRoute::METGetWMSPicklistNumber(pickingRouteId, inventLocation.METCSDWarehouse, metSalesTable.InternalCrossDockOrder);

        // Process the SO/picking list number from shipment one by one
        super();
    }
}

/// <summary>
/// Method to set the fields for <c>METTMSShipmentTable</c> record
/// For packing slip need to set the delivery note number fields from the delivery note posting
/// </summary>
/// <param name = "_tmsShipmentTable"><c>METTMSShipmentTable</c> record</param>
protected void setTMSShipmentFields(METTMSShipmentTable _tmsShipmentTable)
{
    super(_tmsShipmentTable);

    // If a TS record is not found for the selection in step 3a, create a new one with values as defined in Step 3b of the CB624 FSD, 
    // with the extra value for Delivery note number from The Delivery Note journals Delivery note
    _tmsShipmentTable.FinalisationtId = salesOrderShipmentLoadHeader.ShipmentId;
}

/// <summary>
/// Update TS setting clause
/// </summary>
/// <param name = "_uo"><c>SysDaUpdateObject</c> instance</param>
/// <param name = "_palletTotalFootprint">Pallet total footprint</param>
/// <param name = "_updateFinalisationId">Update finalisation id</param>
void updateTMSShipmentSettingClause(SysDaUpdateObject _uo, METQty _palletTotalFootprint, boolean _updateFinalisationId)
{
    super(_uo, _palletTotalFootprint, _updateFinalisationId);

    // this is to exclude shipment delivery note update when a TSO is removed from previous TS
    if (_updateFinalisationId)
    {
        _uo.settingClause().add(fieldStr(METTMSShipmentTable, FinalisationtId), new SysDaValueExpression(salesOrderShipmentLoadHeader.ShipmentId));
    }
}

/// <summary>
/// Method to set the fields for <c>METTMSShipmentOrderTable</c> record
/// </summary>
/// <param name = "_tmsShipmentOrderTable"><c>METTMSShipmentOrderTable</c> record</param>
protected void setTMSShipmentOrderFields(METTMSShipmentOrderTable _tmsShipmentOrderTable)
{
    super(_tmsShipmentOrderTable);

    // Step 3d: Create TSO record
    // As this is an order not processed by “TMS Engine” in past, create a TSO record to capture details of this order similar to 
    // what was defined in “Step 3d” of the CB624 FSD, with the following differences an extra Pick List ID field as defined in the table below.
    _tmsShipmentOrderTable.PickListId = salesOrderShipmentLoadLines.PickingListNum;

    // If any of the lines on the SO have a warehouse with SuppWhsHasCCR = Yes
    // New calc formulas for Repack case count – Security/Non Security and Case count – Shipped/Security
    if (hasCCR)
    {
        this.setTMSShipmentOrderFieldsCCR(_tmsShipmentOrderTable);
    }
}

/// <summary>
/// Method to set the CCR fields for <c>METTMSShipmentOrderTable</c> record
/// </summary>
/// <param name = "_tmsShipmentOrderTable"><c>METTMSShipmentOrderTable</c> record</param>
protected void setTMSShipmentOrderFieldsCCR(METTMSShipmentOrderTable _tmsShipmentOrderTable)
{
    METWHSPalletVolume  sumRepackContainersCaseVolumeCCR, sumRepackContainersToteVolumeCCR;
    int                 sumRepackContainersQtyCCR, sumRepackContainersQtyTOBCCR, sumRepackContainersQtyNotTOBCCR;
    METWHSPalletWeight  sumRepackContainersToteWeightCCR;

    // calc RepackContainersByCommodity for the order with LineCommodity = TOB and <> TOB
    METTMSEngineSalesOrderProccessLinesTmp  linesTmpTOB, linesTmpNotTOB;
    linesTmpTOB.linkPhysicalTableInstance(proccessLinesTmp);
    linesTmpNotTOB.linkPhysicalTableInstance(proccessLinesTmp);

    // BrokenCaseItemQtySecurity and BrokenCaseItemQtyNonSecurity are sum from temp table
    select sum(RepackCountNonSecurity), sum(RepackCountSecurity) from linesTmpTOB where linesTmpTOB.LineCommodity == METConstants::tobCommodity;
    select sum(RepackCountNonSecurity), sum(RepackCountSecurity) from linesTmpNotTOB where linesTmpNotTOB.LineCommodity != METConstants::tobCommodity;

    [sumRepackContainersQtyCCR,
     sumRepackContainersQtyTOBCCR,
     sumRepackContainersQtyNotTOBCCR,
     sumRepackContainersCaseVolumeCCR,
     sumRepackContainersToteVolumeCCR,
     sumRepackContainersToteWeightCCR] = ccrHelper.getSumCommodityResults();

    // Case count – Shipped
    // Add Count(CCR_RepackContainersByCommodity) for all CCR records for the SO to existing calculated value
    _tmsShipmentOrderTable.CaseCountShipped += sumRepackContainersQtyCCR;

    // Repack case count – Security
    // Sum(RepackContainersByCommodity) for the order with LineCommodity = TOB
    // + Count(CCR_RepackContainersByCommodity) for CCR records for the SO with CCR_LineCommodity = TOB.
    _tmsShipmentOrderTable.RepackCaseCountSecurity = this.getRepackContainersByCommodity(linesTmpTOB.RepackCountSecurity, linesTmpTOB.RepackCountNonSecurity)
                                                   + sumRepackContainersQtyTOBCCR;

    // Repack case count – Non security
    // Sum(RepackContainersByCommodity) for the order with LineCommodity <> TOB
    // + Count(CCR_RepackContainersByCommodity) for CCR records for the SO with CCR_ LineCommodity <> TOB
    _tmsShipmentOrderTable.RepackCaseCountNonSecurity = this.getRepackContainersByCommodity(linesTmpNotTOB.RepackCountSecurity, linesTmpNotTOB.RepackCountNonSecurity)
                                                      + sumRepackContainersQtyNotTOBCCR;

    // Case count – Security
    // Sum(RepackContainersByCommodity) for all LineCommodity-s on the order with LineCommodity = TOB
    // + Count(CCR_RepackContainersByCommodity) for all CCR records for the SO with CCR_LineCommodity = TOB
    _tmsShipmentOrderTable.CaseCountSecurity = _tmsShipmentOrderTable.RepackCaseCountSecurity;
}

/// <summary>
/// Shipping date variable from the shipment header
/// </summary>
/// <returns>Shipping date based on CB626 formula</returns>
TransDate shippingDate()
{
    return salesOrderShipmentLoadHeader.ConfirmedShipDate;
}

/// <summary>
/// Delivery date variable from the shipment header
/// </summary>
/// <returns>Delivery date based on CB626 formula</returns>
TransDate deliveryDate()
{
    return salesOrderShipmentLoadHeader.ReceiptDateConfirmed;
}

/// <summary>
/// Create an instance of <c>METTMSShipmentItemGroupHelper</c>
/// </summary>
/// <param name = "_processLinesTmp">Temporary TMS calculation table</param>
/// <param name = "_tmsShipmentOrderIdentifier">TSO identifier</param>
/// <param name = "_isToteCustomer">Customer uses totes</param>
/// <param name = "_headerInventLocationId">Header warehouse</param>
/// <param name = "_hasCCR">If any of the lines on the SO have a warehouse with SuppWhsHasCCR = Yes</param>
/// <returns>New instance of <c>METTMSShipmentItemGroupHelper</c></returns>
METTMSShipmentItemGroupHelper getTSIGHelperInstance(METTMSEngineSalesOrderProccessLinesTmp _processLinesTmp, METTMSShipmentOrderIdentifier _tmsShipmentOrderIdentifier, boolean _isToteCustomer, InventLocationId _headerInventLocationId, boolean _hasCCR)
{
    return METTMSShipmentItemGroupHelper::construct(_processLinesTmp,
                                                    _tmsShipmentOrderIdentifier,
                                                    _isToteCustomer,
                                                    _headerInventLocationId,
                                                    _hasCCR,
                                                    ccrHelper);
}

